import{_ as t,c as i,o as a,ag as n}from"./chunks/framework.CQuhCYrb.js";const m=JSON.parse('{"title":"Create-invite","description":"","frontmatter":{"title":"Create-invite"},"headers":[],"relativePath":"general/create-invite.md","filePath":"general/create-invite.md","lastUpdated":null}'),r={name:"general/create-invite.md"};function o(s,e,l,c,h,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="create-invite" tabindex="-1">Create-invite <a class="header-anchor" href="#create-invite" aria-label="Permalink to &quot;Create-invite&quot;">​</a></h1><h2 id="creating-an-invite-link" tabindex="-1">Creating an Invite Link <a class="header-anchor" href="#creating-an-invite-link" aria-label="Permalink to &quot;Creating an Invite Link&quot;">​</a></h2><p>There are times when you want to create an invite link that will expire after a certain amount of time. This will allow a user or many people to create accounts setting their own usernames and passwords making it easier for admin who don’t need to <a href="/general/create-user.html">user</a></p><p>Return to <a href="/general/admin.html">Admin Links</a></p><h3 id="command-line-version" tabindex="-1">Command Line Version <a class="header-anchor" href="#command-line-version" aria-label="Permalink to &quot;Command Line Version&quot;">​</a></h3><p>Follow the steps from the github repo: <a href="https://github.com/irregularchat/authentik-account-creation" target="_blank" rel="noreferrer">https://github.com/irregularchat/authentik-account-creation</a></p><p>This uses your admin API with a python script which will create a user, set passwords, create invite links and configure it with a basic community message to send to a user.</p><h3 id="create-invite-link" tabindex="-1">Create Invite Link <a class="header-anchor" href="#create-invite-link" aria-label="Permalink to &quot;Create Invite Link&quot;">​</a></h3><p>In the Admin interface of your authentik instance, select Directory &gt; Invitations in the left side menu. - Direct Link: <a href="https://sso.irregularchat.com/if/admin/#/flow/stages/invitations" target="_blank" rel="noreferrer">https://sso.irregularchat.com/if/admin/#/flow/stages/invitations</a></p><p>Click Create (Blue Button near the Search option) Fill in : 1. Name: Lable for the Inivte code. Is this for an email you are sending out? for an in person event? For one Person. This will help determine how users where added. 1. Expires: The default is not much time. Set this code for enough time for a user to create an account. Typically about 2 hours has worked out well. 1. Flow: Select <code>Simple-Enrollment-Flow</code> 1. Custom Attributes: Leave as is 1. Single Use: If this is specifcally for only 1 user, leave this enabled.</p><h3 id="copying-the-invite-url" tabindex="-1">Copying the Invite URL <a class="header-anchor" href="#copying-the-invite-url" aria-label="Permalink to &quot;Copying the Invite URL&quot;">​</a></h3><p>In the Admin interface of your authentik instance, select Directory &gt; Invitations in the left side menu. - Direct Link: <a href="https://sso.irregularchat.com/if/admin/#/flow/stages/invitations" target="_blank" rel="noreferrer">https://sso.irregularchat.com/if/admin/#/flow/stages/invitations</a> You’ll see existing invitations. Find your recently created invitation: 1. Select the <code>&amp;gt;</code> next to the checkmark for that invitation 1. Copy the link from <code>Link to use the invitation.</code> 1. Provide that link to user.</p>',12)])])}const p=t(r,[["render",o]]);export{m as __pageData,p as default};
